# Generated by build.py from recipe.yml for recipe surl-reset-by-copying-a-clean-directory. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'clean', 'held' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'clean/counter.txt'), "1`n")
[IO.File]::WriteAllText((Join-Path $PWD 'held/counter.txt'), "1`n")
[IO.File]::WriteAllText((Join-Path $PWD 'fresh-copy.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# Runs one test on a fresh copy of clean/: copies it to data/, starts surl on the copy,`n# runs the test, stops surl. Usage: sh fresh-copy.sh <port> [keep]`n#   keep  start on data/ as the last test left it, without copying clean/ again`nurl=http://127.0.0.1:`$1/`nif [ `"`$2`" != keep ]; then`n  rm -rf data && cp -R clean data || exit 1`nfi`nsurl -s --directory data --user tester:secret --allow-uploads `"`$url`" &`npid=`$!`ntries=0`nuntil curl -s -o /dev/null `"`$url`"; do        # wait until surl answers`n  tries=`$((tries + 1))`n  if [ `"`$tries`" -ge 50 ]; then echo `"surl did not start`" >&2; kill `"`$pid`"; exit 1; fi`n  sleep 0.1`ndone`n# The test: read the counter, write it back one higher, read it again.`nn=`$(curl -s --digest -u tester:secret `"`${url}counter.txt`")`necho `"`$n`"`necho `$((n + 1)) | curl -s --digest -u tester:secret -T - `"`${url}counter.txt`"`ncurl -s --digest -u tester:secret `"`${url}counter.txt`"`nkill `"`$pid`"`nwait `"`$pid`" 2>/dev/null`nexit 0`n")
sh fresh-copy.sh 8080
